#- # seeds.rb --- the reference's own data, as `create!` calls.
#- #
#- # The rows are the reference's `solar.data.json`, joined to their
#- # entity in the model so each row carries the class that inserts it.
#- #
#- # READS `$.sequence`, NOT `$.entity`, for the reason migrate.rb does:
#- # a map is walked in sorted-key order, and a moon whose planet has not
#- # been inserted yet fails `belongs_to`. The planets go in first
#- # because the model says they do.
#- @"../model.aon"
#-
#- out: file("db/seeds.rb", [
#-   [
# Generated by `aontu render` from model.aon. Do not edit.
#
# The data is the reference's own: `ref/solar.data.json`, included by
# the model rather than copied, so these rows and the ones the
# reference app serves cannot drift apart.

Moon.delete_all
Planet.delete_all
#-   ]
#-
#-   # A SECOND FRAGMENT, not a call in the first one's list: a dispatch
#-   # splices its pieces into the BODY that holds it, and a fragment's
#-   # `n` is a list of pieces rather than a body, so an `emit` beside
#-   # literals there arrives as one nested list and the vocabulary
#-   # refuses it. One fragment per thing that produces lines.
#-   emit($.sequence, {
#-     match: class: string
#-     replace: TITLE: .plural
#-     body: [

# TITLE
#-
#-       # ONE RULE PER CLASS, discriminated by a key every row carries with
#-       # a distinct value. This is the one generator that names the
#-       # entities, and it is the one whose data is named per entity in the
#-       # reference too: `$.seed.planet` and `$.seed.moon`. A generic rule
#-       # would have to build the argument list from the row's own keys,
#-       # which needs the entity's field list at the row's node --- and a
#-       # nested dispatch cannot see the node the outer one matched.
#-       emit(.rows, [
#-         {
#-           match: class: "Planet"
#-           replace: { ID:.id NAME:.name KIND:.kind DIAM:.diameter }
#-           body: [
Planet.create!(id: "ID", name: "NAME", kind: "KIND", diameter: DIAM)
#-           ]
#-         }
#-         {
#-           match: class: "Moon"
#-           replace: { ID:.id NAME:.name OF:.planet_id KIND:.kind DIAM:.diameter }
#-           body: [
Moon.create!(id: "ID", name: "NAME", planet_id: "OF", kind: "KIND", diameter: DIAM)
#-           ]
#-         }
#-       ])
#-     ]
#-   })
#- ])
